<?php
require __DIR__.'/../app/bootstrap.php';
$subjectId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$subjectId)redirect('index.php');
$s=$pdo->prepare("SELECT id,name,description FROM subjects WHERE id=?");$s->execute([$subjectId]);$subject=$s->fetch();if(!$subject){http_response_code(404);exit('Vak niet gevonden.');}
$s=$pdo->prepare("SELECT t.id,t.title,t.description,tp.name topic_name,COUNT(q.id) question_count FROM tests t JOIN topics tp ON tp.id=t.topic_id LEFT JOIN questions q ON q.test_id=t.id WHERE tp.subject_id=? AND t.is_active=1 GROUP BY t.id ORDER BY tp.name,t.title");$s->execute([$subjectId]);$tests=$s->fetchAll();
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($subject['name'])?> - Leren</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><a href="index.php">&larr; Alle vakken</a><h1 class="mt-3"><?=e($subject['name'])?></h1><?php if($subject['description']):?><p class="text-secondary"><?=e($subject['description'])?></p><?php endif;?><div class="row g-3"><?php $topic='';foreach($tests as $t): if($topic!==$t['topic_name']):$topic=$t['topic_name'];?><div class="col-12"><h2 class="h4 mt-3"><?=e($topic)?></h2></div><?php endif;?><div class="col-md-6 col-lg-4"><div class="card h-100 shadow-sm"><div class="card-body"><h3 class="h5"><?=e($t['title'])?></h3><p><?=e($t['description'])?></p><div class="small text-secondary mb-3"><?=$t['question_count']?> vragen</div><a class="btn btn-primary" href="quiz.php?id=<?=$t['id']?>">Start toets</a></div></div></div><?php endforeach;?></div><?php if(!$tests):?><div class="alert alert-info">Er zijn nog geen actieve toetsen voor dit vak.</div><?php endif;?></main></body></html>
